<section class="page-hero"><p class="eyebrow"><?= e(country()->name()) ?></p><h1>Contact support</h1><p class="lead"><?= e($branding['contact_text']??'Our support team is here to help.') ?></p></section><section class="section grid two"><article class="card"><h2>Support details</h2><?php if($branding['support_email']): ?><p><strong>Email</strong><br><a href="mailto:<?= e($branding['support_email']) ?>"><?= e($branding['support_email']) ?></a></p><?php endif;?><?php if($branding['support_phone']): ?><p><strong>Phone</strong><br><?= e($branding['support_phone']) ?></p><?php endif;?><?php if($branding['support_whatsapp']): ?><p><strong>WhatsApp</strong><br><?= e($branding['support_whatsapp']) ?></p><?php endif;?><?php if($branding['business_address']): ?><p><strong>Address</strong><br><?= nl2br(e($branding['business_address'])) ?></p><?php endif;?><?php if($branding['support_hours']): ?><p><strong>Hours</strong><br><?= e($branding['support_hours']) ?></p><?php endif;?></article><article class="card"><h2>Send a message</h2><form method="post" action="<?= e(route('contact.submit')) ?>" class="form-stack"><?= app('csrf')->input() ?><input class="honeypot" tabindex="-1" autocomplete="off" name="website"><label class="field">Name<input name="name" required></label><label class="field">Email<input type="email" name="email" required></label><label class="field">Subject<input name="subject" required></label><label class="field">Message<textarea name="message" rows="6" required></textarea></label><button class="button">Send message</button></form></article></section>
